let db = DATA_FALLBACK; // Default to fallback immediately, will re-load from JSON if fetch succeeds
let activeCategory = "all";
let searchQuery = "";

document.addEventListener('DOMContentLoaded', () => {
    loadDatabase();
});

/**
 * Loads publication database from data.json with fallback logic.
 */
function loadDatabase() {
    // Attempt standard dynamic fetch
    fetch('data.json')
        .then(response => {
            if (!response.ok) throw new Error('Network response failure');
            return response.json();
        })
        .then(data => {
            console.log("Database initialized via fetch('data.json').");
            db = data;
            initCMS();
        })
        .catch(err => {
            console.warn("CORS/Fetch limitation detected. Initializing database with integrated fail-safe data.", err);
            // Even if fetch fails, load the fallback database
            initCMS();
        });
}

/**
 * Initializes CMS page-specific controls.
 */
function initCMS() {
    const isLibraryPage = document.getElementById('library-grid') !== null;
    const isTimesPage = document.getElementById('times-grid') !== null;

    if (isLibraryPage) {
        renderLibrary();
        initFilters('library');
    }

    if (isTimesPage) {
        renderTimes();
        initFilters('times');
        initReadingModal();
    }
}

/**
 * Setup tag selectors and search forms
 */
function initFilters(type) {
    const searchInput = document.getElementById('search-input');
    const filterTags = document.querySelectorAll('.tag');

    // Real-time search key listener
    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            searchQuery = e.target.value.toLowerCase().trim();
            if (type === 'library') renderLibrary();
            if (type === 'times') renderTimes();
        });
    }

    // Category click listeners
    filterTags.forEach(tag => {
        tag.addEventListener('click', () => {
            filterTags.forEach(t => t.classList.remove('active'));
            tag.classList.add('active');
            activeCategory = tag.getAttribute('data-category');
            
            if (type === 'library') renderLibrary();
            if (type === 'times') renderTimes();
        });
    });
}

/**
 * RENDER LIBRARY BOOKS (library.html)
 */
function renderLibrary() {
    const grid = document.getElementById('library-grid');
    if (!grid) return;

    grid.innerHTML = "";
    
    // Filter books array
    const filtered = db.library.filter(book => {
        const matchesCategory = activeCategory === 'all' || book.category.toLowerCase().includes(activeCategory.replace('-', ' '));
        const matchesSearch = book.title.toLowerCase().includes(searchQuery) ||
                              book.author.toLowerCase().includes(searchQuery) ||
                              book.summary.toLowerCase().includes(searchQuery);
        return matchesCategory && matchesSearch;
    });

    if (filtered.length === 0) {
        grid.innerHTML = `<div class="cms-grid-empty">Zero academic publications matched the query indices.</div>`;
        return;
    }

    filtered.forEach(book => {
        const card = document.createElement('div');
        card.className = "book-card reveal-element revealed"; // Add revealed for instant beautiful rendering
        card.innerHTML = `
            <div class="book-spine-visual">
                <div class="book-spine-text">${book.spineText}</div>
                <div class="book-spine-telemetry">${book.telemetry}</div>
            </div>
            <div class="book-info">
                <span class="book-tag">${book.category}</span>
                <h3>${book.title}</h3>
                <div class="book-author">By ${book.author}</div>
                <p class="book-summary">${book.summary}</p>
                <div class="book-meta-footer">
                    <span>Year: ${book.year}</span>
                    <span>Pages: ${book.pages}</span>
                </div>
            </div>
        `;
        grid.appendChild(card);
    });
}

/**
 * RENDER FINANCIAL JOURNAL TIMES ARTICLES (times.html)
 */
function renderTimes() {
    const grid = document.getElementById('times-grid');
    if (!grid) return;

    grid.innerHTML = "";

    // Filter times array
    const filtered = db.times.filter(article => {
        const matchesCategory = activeCategory === 'all' || article.category.toLowerCase().includes(activeCategory.replace('-', ' '));
        const matchesSearch = article.title.toLowerCase().includes(searchQuery) ||
                              article.excerpt.toLowerCase().includes(searchQuery) ||
                              article.content.toLowerCase().includes(searchQuery);
        return matchesCategory && matchesSearch;
    });

    if (filtered.length === 0) {
        grid.innerHTML = `<div class="cms-grid-empty">Zero journal entries matched the query indices.</div>`;
        return;
    }

    filtered.forEach(article => {
        const card = document.createElement('div');
        card.className = "article-card reveal-element revealed";
        card.setAttribute('data-id', article.id);
        card.innerHTML = `
            <div class="article-meta">
                <span>${article.category}</span>
                <span>${article.readTime}</span>
            </div>
            <h3>${article.title}</h3>
            <p class="article-excerpt">${article.excerpt}</p>
            <div class="article-footer">
                <span>${article.date}</span>
                <span class="article-read-more">
                    Read Audit Analysis
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg>
                </span>
            </div>
        `;

        // Click interaction opens full reader slide drawer
        card.addEventListener('click', () => {
            openArticleReader(article);
        });

        grid.appendChild(card);
    });
}

/**
 * SIDE DRAWER READING MODAL OVERLAY (times.html)
 */
function initReadingModal() {
    const modal = document.getElementById('reading-modal');
    if (!modal) return;

    const overlay = modal.querySelector('.modal-overlay');
    const closeBtn = modal.querySelector('.modal-close-btn');

    const closeModal = () => {
        modal.classList.remove('active');
        document.body.style.overflow = ""; // restore scroll
    };

    if (overlay) overlay.addEventListener('click', closeModal);
    if (closeBtn) closeBtn.addEventListener('click', closeModal);
}

function openArticleReader(article) {
    const modal = document.getElementById('reading-modal');
    if (!modal) return;

    const categoryEl = modal.querySelector('.modal-header-meta span');
    const titleEl = modal.querySelector('.modal-body h2');
    const bylineEl = modal.querySelector('.modal-article-byline');
    const contentEl = modal.querySelector('.modal-real-content');

    if (categoryEl) categoryEl.textContent = `${article.category} | ${article.readTime}`;
    if (titleEl) titleEl.textContent = article.title;
    if (bylineEl) bylineEl.textContent = `Published: ${article.date} • Authored by ${article.author}`;
    if (contentEl) contentEl.innerHTML = article.content;

    modal.classList.add('active');
    document.body.style.overflow = "hidden"; // lock page scroll
}
